#include <CoreFoundation/CoreFoundation.h>
#include <IOKit/IOKitLib.h>
#include <IOKit/pwr_mgt/IOPM.h>
#include <stdio.h>
int main(void) {
 io_registry_entry_t root = IORegistryEntryFromPath(kIOMainPortDefault, kIOPowerPlane ":/IOPowerConnection/IOPMrootDomain");
 if (!root) return 2;
 int zero = 0;
 CFNumberRef value = CFNumberCreate(NULL, kCFNumberIntType, &zero);
 IOReturn result = IORegistryEntrySetCFProperty(root, CFSTR(kIOPMSettingDebugWakeRelativeKey), value);
 CFRelease(value); IOObjectRelease(root);
 printf("WakeRelativeToSleep reset to 0; IOKit result=0x%08x\n", result);
 return result == kIOReturnSuccess ? 0 : 1;
}
